/// <summary>
/// AVA FormControl AVASalesGroup
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVASalesGroup))]
final class AVASalesTableListPageFrmCtr_AVASalesGroup_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret = next modified();

    FormDataSource avaSalesTable_ds = this.formRun().dataSource(tableStr(SalesTable));
    CommissSalesGroup salesGroupLoc = this.valueStr();


    if (salesGroupLoc)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, SalesGroup)).value(queryValue(salesGroupLoc));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, SalesGroup)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return ret;
}
